window.docContents[23].resolve({"/Tactics/#Tactics":{"contents":"\n\n\n\n\n\n\n\n\n\nThis chapter introduces several additional proof strategies\nand tactics that allow us to begin proving more interesting\nproperties of functional programs.We will see:* how to use auxiliary lemmas in both \"forward-\" and\n  \"backward-style\" proofs;* how to reason about data constructors -- in particular, how to\n  use the fact that they are injective and disjoint;* how to strengthen an induction hypothesis, and when such\n  strengthening is required; and* more details on how to reason by case analysis.\n\nimport LF.Poly\nimport LF.CustomTactics\n\n\nOA: added these to use Lean's Nat.\n\n\n\nopen Nat (add_comm add_assoc add_zero add_succ mul_one succ_sub_succ)\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n","context":"Logical Foundations","header":"7. Tactics: More Basic Tactics","id":"/Tactics/#Tactics"}});